function binarySearch(arr, searchItem) {
  let low = 0;
  let high = arr.length - 1;
  let mid;
  while(low <= high) {
    mid = Math.floor((low + high) / 2);
    if(arr[mid] === searchItem) {
      return mid;
    } else if(arr[mid] < searchItem) {
      low = mid + 1;
    } else {
      high = mid - 1;
    }
  }
  return -1;
}

